    85  std::string BmffImage::toAscii(uint32_t n) {
    86    const auto p = reinterpret_cast<const char*>(&n);
    87    std::string result(4, '.');
    88    std::transform(p, p + 4, result.begin(), [](char c) {
    89      if (32 <= c && c < 127)
    90        return c;  // only allow 7-bit printable ascii
    91      if (c == 0)
    92        return '_';  // show 0 as _
    93      return '.';    // others .
    94    });
    95    if (!isBigEndianPlatform())
    96      std::reverse(result.begin(), result.end());
    97    return result;
    98  }
