   212  template <typename T>
   213  std::istream& fromStreamToRational(std::istream& is, T& r) {
   214    // http://dev.exiv2.org/boards/3/topics/1912?r=1915
   215    if (std::tolower(is.peek()) == 'f') {
   216      char F = 0;
   217      float f = 0.F;
   218      is >> F >> f;
   219      f = 2.0F * std::log(f) / std::log(2.0F);
   220      r = Exiv2::floatToRationalCast(f);
   221    } else {
   222      int32_t nominator = 0;
   223      int32_t denominator = 0;
   224      char c('\0');
   225      is >> nominator >> c >> denominator;
   226      if (c != '/')
   227        is.setstate(std::ios::failbit);
   228      if (is)
   229        r = {nominator, denominator};
   230    }
   231    return is;
   232  }
