   674      return "application/octet-stream";
   675    }();
   676    if (bTrace) {
   677      out << Internal::stringFormat("width,height,size = %zu,%zu,%zu", nativePreview.width_, nativePreview.height_,
   678                                    nativePreview.size_);
   679    }
   680    nativePreviews_.push_back(std::move(nativePreview));
